    if (!pref) {
        statusMessage.textContent = 'Please select a notification preference.';
        statusMessage.className = 'error';

        // Focus the first radio button to help user fix it
        const firstRadio = form.querySelector('input[type="radio"]');
        if (firstRadio) firstRadio.focus();
        return;
    }

    // Simulate API call
    statusMessage.textContent = 'Saving...';
    statusMessage.className = '';

    setTimeout(() => {
        statusMessage.textContent = `Success! Your preference "${capitalize(pref)}" has been saved.`;
        statusMessage.className = 'success';
    }, 800);
});

