", direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/radio-button-group--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s1/a11y-test.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents="const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    page.on('console', msg => console.log('PAGE LOG:', msg.text()));

    // Read local files
    const html = fs.readFileSync('index.html', 'utf8');
    const css = fs.readFileSync('style.css', 'utf8');
    const js = fs.readFileSync('script.js', 'utf8');

    // Set content and inject CSS/JS
    await page.setContent(`
        <!DOCTYPE html>
        <html>
        <head>
            <style>${css}</style>
        </head>
        <body>
            ${html}
            <script>${js}</script>
        </body>
        </html>
    `);

    // Inject axe-core
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    // Run axe
    const results = await page.evaluate(async () => {
        const btn = document.querySelector('button');
        const style = window.getComputedStyle(btn);
        console.log(`Button color: ${style.color}, background-color: ${style.backgroundColor}`);
        return await window.axe.run();
    });

    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    process.exit(wcag.length > 0 ? 1 : 0);
})();
