document.getElementById('preferences-form').addEventListener('submit', function(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const pref = formData.get('notification-pref');
    const statusMessage = document.getElementById('status-message');

    if (!pref) {
        statusMessage.textContent = 'Please select a notification preference.';
        statusMessage.className = 'error';

        // Focus the first radio button to help user fix it
        const firstRadio = form.querySelector('input[type="radio"]');
        if (firstRadio) firstRadio.focus();
        return;
    }

    // Simulate API call
    statusMessage.textContent = 'Saving...';
    statusMessage.className = '';

    setTimeout(() => {
        statusMessage.textContent = `Success! Your preference "${capitalize(pref)}" has been saved.`;
        statusMessage.className = 'success';
    }, 800);
});

function capitalize(string) {
    if (string === 'sms') return 'SMS';
    return string.charAt(0).toUpperCase() + string.slice(1);
}
